    border-radius: var(--radius);
    font-size: 0.88rem;
    border: none;
    margin-bottom: 28px;
  }
  .alert-success { background: rgba(34,197,94,0.1); color: #86efac; }
  .alert-danger  { background: rgba(239,68,68,0.1);  color: #fca5a5; }

  /* sections */
